import React from 'react';
import { Link } from 'react-router-dom';

function Home() {
  return (
    <main>
      <div>
        <h2>Welcome to the Food Truck Vendor Application</h2>
        <p>
          Discover the Best Food Trucks in Chennai & Bangalore! Join our community of skilled vendors 
          and connect with food lovers who are eager to explore culinary delights on wheels.
        </p>
        <p>
          Whether you're a vendor looking to share your delicious offerings or a foodie wanting to 
          explore vibrant street food, you've come to the right place!
        </p>
        <Link to="/apply">Become a Vendor</Link>
      </div>
    </main>
  );
}

export default Home;
